INSERT INTO public.motivational_content (content_en, content_ar, author_en, author_ar, category) VALUES
('Knowledge without action is insanity, and action without knowledge is vanity.', 'العلم بلا عمل جنون، والعمل بلا علم ضلال.', 'Imam Al-Ghazali', 'الإمام الغزالي', 'general'),
('The cure for ignorance is to question, but the cure for arrogance is to listen.', 'علاج الجهل هو السؤال، ولكن علاج الكبرياء هو الاستماع.', 'Ibn Hazm', 'ابن حزم', 'general'),
('Patience in times of hardship is a sign of wisdom.', 'الصبر في أوقات الشداد هو علامة الحكمة.', 'Al-Farabi', 'الفارابي', 'wellness'),
('The greatest wealth is wisdom; the greatest poverty is ignorance.', 'أعظم ثروة هي الحكمة؛ وأعظم فقر هو الجهل.', 'Ibn Sina (Avicenna)', 'ابن سينا (أفيروسين)', 'general'),
('A leader who serves his people is a true leader; one who serves himself is a tyrant.', 'القائد الذي يخدم شعبه هو قائد حقيقي؛ والذي يخدم نفسه هو طاغية.', 'Al-Mawardi', 'الماوردي', 'leadership'),
('Excellence in work is an act of worship.', 'الإتقان في العمل هو عبادة.', 'Prophetic Tradition', 'حديث نبوي', 'service'),
('The pen is the tongue of the mind.', 'القلم هو لسان العقل.', 'Al-Jahiz', 'الجاحظ', 'general'),
('He who knows himself knows his Lord.', 'من عرف نفسه عرف ربه.', 'Ibn Arabi', 'ابن عربي', 'wellness'),
('The seeker of knowledge is on the path of God until death.', 'طالب العلم على طريق الله حتى الموت.', 'Al-Tabari', 'الطبري', 'general'),
('Wisdom is the lost property of the believer; wherever he finds it, he has more right to it.', 'الحكمة ضالة المؤمن؛ حيث وجدها فهو أحق بها.', 'Prophetic Tradition', 'حديث نبوي', 'leadership');;
